UNITS = {
    "h": 3600,
    "m": 60,
    "s": 1,
}


def parse_duration(text):
    """Return the number of seconds in a duration string."""
    # BUG: only handles a single <number><unit> pair, and no fractions.
    unit = text[-1]
    return int(text[:-1]) * UNITS[unit]

